    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        validateByRatePlan(request);
    35	
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(
    49	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    50	        return store.add(request, price);
    51	    }
    52	
    53	    private void validateByRatePlan(NewReservation request) {
    54	        switch (request.ratePlan()) {
    55	            case CORPORATE -> {
    56	                if (request.companyCode().isEmpty()
    57	                        || !PriceCalculator.isValidCorporateCode(request.companyCode().get())) {
    58	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid company code for corporate plan");
    59	                }
    60	            }
    61	            case WEEKEND_PACKAGE -> {
    62	                if (!PriceCalculator.isWeekendFridayToSunday(request.checkIn(), request.checkOut())) {
    63	                    throw new HotelException(
    64	                            ErrorCode.INVALID_REQUEST,
    65	                            "weekend package requires check-in on Friday and check-out on Sunday");
    66	                }
    67	            }
    68	            case LONG_STAY -> {
    69	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(
    70	                        request.checkIn(), request.checkOut());
    71	                if (nights < PriceCalculator.LONG_STAY_MIN_NIGHTS) {
    72	                    throw new HotelException(
    73	                            ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
    74	                }
    75	            }
