   102	    /**
   103	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   104	     * reservation was never paid, so nothing comes back).
   105	     */
   106	    public synchronized Reservation cancel(long reservationId) {
   107	        Reservation reservation = find(reservationId);
   108	        if (reservation.status() != ReservationStatus.PENDING
   109	                && reservation.status() != ReservationStatus.CONFIRMED) {
   110	            throw notAllowed(reservation, "cancel");
   111	        }
   112	        BigDecimal refund = calculateRefund(reservation);
   113	        reservation.cancel(refund);
   114	        store.update(reservation);
   115	        return reservation;
   116	    }
   117	
   118	    private BigDecimal calculateRefund(Reservation reservation) {
   119	        return switch (reservation.ratePlan()) {
   120	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   121	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   122	            case WEEKEND_PACKAGE -> PriceCalculator.cents(
   123	                    reservation.amountPaid().multiply(new BigDecimal("0.5")));
   124	        };
   125	    }
   126	
   127	    public synchronized Reservation checkIn(long reservationId) {
   128	        Reservation reservation = find(reservationId);
   129	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   130	            throw notAllowed(reservation, "check in");
   131	        }
   132	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   133	        store.update(reservation);
   134	        return reservation;
   135	    }
   136	
   137	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   138	    public synchronized ReservationReceipt checkOut(long reservationId) {
   139	        Reservation reservation = find(reservationId);
   140	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   141	            throw notAllowed(reservation, "check out");
   142	        }
   143	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   144	        store.update(reservation);
   145	        return new ReservationReceipt(reservation, roomOf(reservation));
   146	    }
   147	
   148	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   149	    public ReservationReceipt receiptCopy(long reservationId) {
   150	        Reservation reservation = find(reservationId);
   151	        if (!reservation.isPaid()) {
   152	            throw notAllowed(reservation, "issue a receipt for");
   153	        }
   154	        return new ReservationReceipt(reservation, roomOf(reservation));
   155	    }
   156	
   157	    private Room roomOf(Reservation reservation) {
   158	        return rooms.find(reservation.roomNumber()).orElseThrow();
   159	    }
